00063 BaseDecNalUnitType::Enum uFromEVC(uint8_t type) {
00064     switch (type) {
00065     case EVCNalType::NONIDR_NUT:
00066     case EVCNalType::IDR_NUT:
00067         return BaseDecNalUnitType::Slice;
00068     case EVCNalType::SPS_NUT:
00069         return BaseDecNalUnitType::SPS;
00070     case EVCNalType::PPS_NUT:
00071         return BaseDecNalUnitType::PPS;
00072 #if defined(EVC_FDIS)
00073     case EVCNalType::FD_NUT:
00074         return BaseDecNalUnitType::Filler;
00075 #endif
00076     case EVCNalType::SEI_NUT:
00077         return BaseDecNalUnitType::SEI;
00078     }
00079 
00080     return BaseDecNalUnitType::Unknown;
00081 }
