00100 
00101 bool BaseDecoderEVC::ParseNalUnit(const uint8_t *nal, uint32_t nalLength) {
00102     bool bSuccess = true;
00103 
00104     uint32_t offset = 0;
00105 
00106     // [forbidden-zero:1, nal_type:6, layer_id_top:1]
00107     m_nal_type = ((nal[offset] >> 1) & 0x3F) - 1;
00108     // [layer_id:5, temporal_id_plus1:3]
00109     m_temporal_id = nal[offset + 1] >> 5;
00110 
00111     offset += 2;
00112 
00113     BaseDecNalUnitType::Enum nalType = uFromEVC(m_nal_type);
00114 
00115     nal += offset;
00116     nalLength -= offset;
00117 
00118     m_currentNalPayload.clear();
00119     m_currentNalPayload.insert(m_currentNalPayload.end(), nal, nal + nalLength);
00120 
00121     m_currentBits = *m_currentNalPayload.data();
00122     m_remainingBits = 8;
00123     m_byteOffset = 0;
00124 
00125     switch (nalType) {
00126     case BaseDecNalUnitType::VPS:
00127         bSuccess = ParseVPS();
00128         break;
00129     case BaseDecNalUnitType::PPS:
00130         bSuccess = ParsePPS();
00131         break;
00132     case BaseDecNalUnitType::SPS:
00133         bSuccess = ParseSPS();
00134         break;
00135     case BaseDecNalUnitType::Slice:
00136         if ((bSuccess = ParseSliceHeader(m_nal_type))) {
00137             HandlePictureOrderCount(m_nal_type, m_temporal_id);
00138         }
00139         break;
00140     case BaseDecNalUnitType::EOS:
00141         break;
00142     default:
00143         break;
00144     }
00145 
00146     return bSuccess;
00147 }
