00232 void BaseDecoderEVC::HandlePictureOrderCount(uint32_t nal_unit_type, uint32_t nuh_temporal_id) {
00233 
00234     if (!m_sps->tool_pocs) {
00235         CHECK(0); // XXX Not handled
00236     } else {
00237         if (nal_unit_type == EVCNalType::IDR_NUT) {
00238             m_slice_header.poc_lsb = 0;
00239             m_poc_val = 0;
00240         } else {
00241             int poc_msb, poc_lsb, max_poc_lsb, prev_poc_lsb, prev_poc_msb;
00242 
00243             poc_lsb = m_slice_header.poc_lsb;
00244             max_poc_lsb = 1 << (m_sps->log2_max_pic_order_cnt_lsb);
00245             prev_poc_lsb = m_prev_poc_val & (max_poc_lsb - 1);
00246             prev_poc_msb = m_prev_poc_val - prev_poc_lsb;
00247             if ((poc_lsb < prev_poc_lsb) && ((prev_poc_lsb - poc_lsb) >= (max_poc_lsb / 2)))
00248                 poc_msb = prev_poc_msb + max_poc_lsb;
00249             else if ((poc_lsb > prev_poc_lsb) && ((poc_lsb - prev_poc_lsb) > (max_poc_lsb / 2)))
00250                 poc_msb = prev_poc_msb - max_poc_lsb;
00251             else
00252                 poc_msb = prev_poc_msb;
00253 
00254             m_poc_val = poc_msb + poc_lsb;
00255 
00256             if (nuh_temporal_id == 0)
00257                 m_prev_poc_val = m_poc_val;
00258         }
00259     }
00260 }
