00262 bool BaseDecoderEVC::ParseSPS() {
00263 
00264     uint32_t seq_parameter_set_id = ReadUE();
00265     if (seq_parameter_set_id >= EVCMaxSPSCount) {
00266         ERR("spsID out of range %d", seq_parameter_set_id);
00267         return false;
00268     }
00269     m_sps = &m_sps_set[seq_parameter_set_id];
00270     m_sps->seq_parameter_set_id = seq_parameter_set_id;
00271 
00272     m_sps->profile_idc = ReadBits(8);
00273     m_sps->level_idc = ReadBits(8);
00274     m_sps->toolset_idc_h = ReadBits(32);
00275     m_sps->toolset_idc_l = ReadBits(32);
00276     m_sps->chroma_format_idc = ReadUE();
00277     m_sps->pic_width_in_luma_samples = ReadUE();
00278     m_sps->pic_height_in_luma_samples = ReadUE();
00279     m_sps->bit_depth_luma = ReadUE() + 8;
00280     m_sps->bit_depth_chroma = ReadUE() + 8;
00281     m_sps->sps_btt_flag = ReadFlag();
00282     if (m_sps->sps_btt_flag) {
00283         m_sps->log2_ctu_size = ReadUE() + 5;
00284         m_sps->log2_min_cb_size = ReadUE() + 2;
00285         m_sps->log2_diff_ctu_max_14_cb_size = ReadUE();
00286         m_sps->log2_diff_ctu_max_tt_cb_size = ReadUE();
00287         m_sps->log2_diff_min_cb_min_tt_cb_size = ReadUE() + 2;
00288     }
00289     m_sps->sps_suco_flag = ReadFlag();
00290     if (m_sps->sps_suco_flag) {
00291         m_sps->log2_diff_ctu_size_max_suco_cb_size = ReadUE();
00292         m_sps->log2_diff_max_suco_min_suco_cb_size = ReadUE();
00293     }
00294 
00295     m_sps->tool_admvp = ReadFlag();
00296     if (m_sps->tool_admvp) {
00297         m_sps->tool_affine = ReadFlag();
00298         m_sps->tool_amvr = ReadFlag();
00299         m_sps->tool_dmvr = ReadFlag();
00300         m_sps->tool_mmvd = ReadFlag();
00301         m_sps->tool_hmvp = ReadFlag();
00302     }
00303 
00304     m_sps->tool_eipd = ReadFlag();
00305     if (m_sps->tool_eipd) {
00306         m_sps->ibc_flag = ReadFlag();
00307         if (m_sps->ibc_flag) {
00308             m_sps->ibc_log_max_size = ReadUE() + 2;
00309         }
00310     }
00311 
00312     m_sps->tool_cm_init = ReadFlag();
00313     if (m_sps->tool_cm_init) {
00314         m_sps->tool_adcc = ReadFlag();
00315     }
00316     m_sps->tool_iqt = ReadFlag();
00317     if (m_sps->tool_iqt) {
00318         m_sps->tool_ats = ReadFlag();
00319     }
00320     m_sps->tool_addb = ReadFlag();
00321     m_sps->tool_alf = ReadFlag();
00322     m_sps->tool_htdf = ReadFlag();
00323     m_sps->tool_rpl = ReadFlag();
00324     m_sps->tool_pocs = ReadFlag();
00325     m_sps->dquant_flag = ReadFlag();
00326     m_sps->tool_dra = ReadFlag();
00327 
00328     if (m_sps->tool_pocs) {
00329         m_sps->log2_max_pic_order_cnt_lsb = ReadUE() + 4;
00330     }
00331 
00332     if (!m_sps->tool_rpl || !m_sps->tool_pocs) {
00333         m_sps->log2_sub_gop_length = ReadUE();
00334         if (m_sps->log2_sub_gop_length == 0) {
00335             m_sps->log2_ref_pic_gap_length = ReadUE();
00336         }
00337     }
00338     if (!m_sps->tool_rpl) {
00339         m_sps->max_num_ref_pics = ReadUE();
00340     } else {
00341         m_sps->sps_max_dec_pic_buffering = ReadUE() + 1;
00342         m_sps->long_term_ref_pics_flag = ReadFlag();
00343         m_sps->rpl1_same_as_rpl0_flag = ReadFlag();
00344         m_sps->num_ref_pic_lists_in_sps0 = ReadUE();
00345     }
00346 
00347     // Ignore rest
00348     // ...
00349 
00350     return true;
00351 }
00352 
00353 bool BaseDecoderEVC::ParsePPS() {
00354     uint32_t pps_pic_parameter_set_id = ReadUE();
00355 
00356     if (pps_pic_parameter_set_id >= EVCMaxPPSCount) {
00357         ERR("ppsID out of range %d", pps_pic_parameter_set_id);
00358         return false;
00359     }
00360 
00361     m_pps = &m_pps_set[pps_pic_parameter_set_id];
00362     m_pps->pic_parameter_set_id = pps_pic_parameter_set_id;
00363     m_pps->seq_parameter_set_id = ReadUE();
00364 
00365     m_pps->num_ref_idx_default_active[0] = ReadUE() + 1;
00366     m_pps->num_ref_idx_default_active[1] = ReadUE() + 1;
00367     m_pps->additional_lt_poc_lsb_len = ReadUE();
00368     m_pps->rpl1_idx_present_flag = ReadFlag();
00369     m_pps->single_tile_in_pic_flag = ReadFlag();
00370     if (!m_pps->single_tile_in_pic_flag) {
00371         m_pps->num_tile_columns = ReadUE() + 1;
00372         m_pps->num_tile_rows = ReadUE() + 1;
00373         m_pps->uniform_tile_spacing_flag = ReadFlag();
00374         if (!m_pps->uniform_tile_spacing_flag) {
00375             for (unsigned i = 0; i < m_pps->num_tile_columns - 1; ++i)
00376                 m_pps->tile_column_width[i] = ReadUE() + 1;
00377             for (unsigned i = 0; i < m_pps->num_tile_rows - 1; ++i)
00378                 m_pps->tile_row_height[i] = ReadUE() + 1;
00379         }
00380         m_pps->loop_filter_across_tiles_enabled_flag = ReadFlag();
00381         m_pps->tile_offset_lens = ReadUE() + 1;
00382     } else {
00383         m_pps->num_tile_columns = 1;
00384         m_pps->num_tile_rows = 1;
00385         m_pps->tile_offset_lens = 1;
00386     }
00387 
00388     m_pps->tile_id_len = ReadUE() + 1;
00389     m_pps->explicit_tile_id_flag = ReadFlag();
00390     if (m_pps->explicit_tile_id_flag) {
00391         for (unsigned i = 0; i <= m_pps->num_tile_rows - 1; ++i)
00392             for (unsigned j = 0; j <= m_pps->num_tile_columns - 1; ++j)
00393                 m_pps->tile_id_val[i][j] = ReadBits(m_pps->tile_id_len);
00394     }
00395 
00396     m_pps->pic_dra_enabled_present_flag = 0;
00397     m_pps->pic_dra_enabled_flag = 0;
00398     if (m_sps->tool_dra) {
00399         m_pps->pic_dra_enabled_present_flag = ReadFlag();
00400         if (m_pps->pic_dra_enabled_present_flag) {
00401             m_pps->pic_dra_enabled_flag = ReadFlag();
00402             if (m_pps->pic_dra_enabled_flag) {
00403                 m_pps->pic_dra_aps_id = ReadBits(3);
00404             }
00405         }
00406     }
00407 
00408     m_pps->arbitrary_slice_present_flag = ReadFlag();
00409     m_pps->constrained_intra_pred_flag = ReadFlag();
00410     m_pps->cu_qp_delta_enabled_flag = ReadFlag();
00411     if (m_pps->cu_qp_delta_enabled_flag)
00412         m_pps->cu_qp_delta_area = ReadUE() + 6;
00413 
00414     return true;
00415 }
00416 
00417 bool BaseDecoderEVC::ParseSliceHeader(uint32_t nal_unit_type) {
00418 
00419     m_slice_header.pic_parameter_set_id = ReadUE();
00420 
00421     m_slice_header.pps = &m_pps_set[m_slice_header.pic_parameter_set_id];
00422     m_slice_header.sps = &m_sps_set[m_slice_header.pps->seq_parameter_set_id];
00423 
00424     PPS *pps = m_slice_header.pps;
00425     SPS *sps = m_slice_header.sps;
00426     SliceHeader *sh = &m_slice_header;
00427 
00428     uint32_t num_tiles_in_slice = 0;
00429 
00430     if (!pps->single_tile_in_pic_flag) {
00431         sh->single_tile_in_slice_flag = ReadFlag();
00432         sh->first_tile_id = ReadBits(pps->tile_id_len);
00433     } else {
00434         sh->single_tile_in_slice_flag = 1;
00435     }
00436 
00437     if (!sh->single_tile_in_slice_flag) {
00438         if (pps->arbitrary_slice_present_flag) {
00439             sh->arbitrary_slice_flag = ReadFlag();
00440         }
00441         if (!sh->arbitrary_slice_flag) {
00442             sh->last_tile_id = ReadBits(pps->tile_id_len);
00443         } else {
00444             sh->num_remaining_tiles_in_slice = ReadUE() + 1;
00445             num_tiles_in_slice = sh->num_remaining_tiles_in_slice + 1;
00446             for (unsigned i = 0; i < num_tiles_in_slice - 1; ++i) {
00447                 sh->delta_tile_id[i] = ReadUE() + 1;
00448             }
00449         }
00450     }
00451 
00452     sh->slice_type = ReadUE();
00453 
00454     if (!sh->arbitrary_slice_flag) {
00455         int first_row_slice, w_tile_slice, first_col_slice, h_tile_slice, w_tile;
00456         w_tile = pps->num_tile_columns;
00457         first_row_slice = sh->first_tile_id / w_tile;
00458         first_col_slice = sh->first_tile_id % w_tile;
00459         w_tile_slice = (sh->last_tile_id % w_tile) - first_col_slice;
00460         h_tile_slice = (sh->last_tile_id / w_tile) - first_row_slice;
00461         num_tiles_in_slice = (w_tile_slice + 1) * (h_tile_slice + 1);
00462     } else {
00463         num_tiles_in_slice = sh->num_remaining_tiles_in_slice + 1;
00464     }
00465 
00466     if (nal_unit_type == EVCNalType::IDR_NUT) {
00467         sh->no_output_of_prior_pics_flag = ReadFlag();
00468     }
00469 
00470     if (sps->tool_mmvd && ((sh->slice_type == SLICE_B) || (sh->slice_type == SLICE_P))) {
00471         sh->mmvd_group_enable_flag = ReadFlag();
00472     } else {
00473         sh->mmvd_group_enable_flag = 0;
00474     }
00475 
00476     if (sps->tool_alf) {
00477         sh->alfChromaIdc = 0;
00478         sh->alf_sh_param_enabledFlag[0] = 0;
00479         sh->alf_sh_param_enabledFlag[1] = 0;
00480         sh->alf_sh_param_enabledFlag[2] = 0;
00481 
00482         sh->alf_on = ReadFlag();
00483         sh->alf_sh_param_enabledFlag[0] = sh->alf_on;
00484         if (sh->alf_on) {
00485             sh->aps_id_y = ReadBits(5);
00486 
00487             bool isCtbAlfOn = ReadFlag();
00488 
00489             sh->alfChromaIdc = ReadBits(2);
00490             sh->alf_sh_param_enabledFlag[1] = sh->alfChromaIdc & 1;
00491             sh->alf_sh_param_enabledFlag[2] = (sh->alfChromaIdc >> 1) & 1;
00492             if (sh->alfChromaIdc == 1) {
00493                 sh->ChromaAlfEnabledFlag = 1;
00494                 sh->ChromaAlfEnabled2Flag = 0;
00495             } else if (sh->alfChromaIdc == 2) {
00496                 sh->ChromaAlfEnabledFlag = 0;
00497                 sh->ChromaAlfEnabled2Flag = 1;
00498             } else if (sh->alfChromaIdc == 3) {
00499                 sh->ChromaAlfEnabledFlag = 1;
00500                 sh->ChromaAlfEnabled2Flag = 1;
00501             } else {
00502                 sh->ChromaAlfEnabledFlag = 0;
00503                 sh->ChromaAlfEnabled2Flag = 0;
00504             }
00505             if (sh->alfChromaIdc && (sps->chroma_format_idc == 1 || sps->chroma_format_idc == 2)) {
00506                 sh->aps_id_ch = ReadBits(5);
00507             }
00508         }
00509         if (sps->chroma_format_idc == 3 && sh->ChromaAlfEnabledFlag) {
00510             sh->aps_id_ch = ReadBits(5);
00511             sh->alfChromaMapSignalled = ReadFlag();
00512         }
00513         if (sps->chroma_format_idc == 3 && sh->ChromaAlfEnabled2Flag) {
00514             sh->aps_id_ch2 = ReadBits(5);
00515             sh->alfChroma2MapSignalled = ReadFlag();
00516         }
00517     }
00518 
00519     if (nal_unit_type != EVCNalType::IDR_NUT) {
00520         if (sps->tool_pocs) {
00521             sh->poc_lsb = ReadBits(sps->log2_max_pic_order_cnt_lsb);
00522         }
00523     }
00524 
00525     return true;
00526 }
